-- Source: FED_COURTLISTENER_INVESTMENTS (1,901,599 rows)  [row count re-verified against the live table 2026-08-11; header had said 500000]
-- Generated by scripts/gen_mart_models.py
-- Fixed 2026-09-20: DATE_CREATED/DATE_MODIFIED/TRANSACTION_DATE were bare
-- try_to_date() calls -- live-confirmed today on TRANSACTION_DATE: 32 of
-- 686,311 filled rows are pure-digit or sign-led strings ('-1' x31, '24312'
-- x1) that a bare cast silently mis-parses to 1969-12-31 / 1970-01-01 instead
-- of erroring. The guarded stg_date macro (macros/staging_casts.sql) reads
-- both shapes NULL instead. Kept on source() (not ref()) -- a matching staging
-- model exists (stg_fed_courtlistener_investments__records) but its cast
-- choices don't line up with this mart's: it types date_created/date_modified
-- as TIMESTAMP (stg_ts) where this mart keeps DATE, and page_number/
-- financial_disclosure_id as NUMBER (stg_int) where this mart keeps them TEXT
-- passthrough -- swapping to ref() would silently change 4 column types, so
-- the bare casts are wrapped in place instead.

with source as (
    select * from {{ source('ripple_raw', 'FED_COURTLISTENER_INVESTMENTS') }}
)

select
    ID as id,
    {{ stg_date('DATE_CREATED') }} as date_created,
    {{ stg_date('DATE_MODIFIED') }} as date_modified,
    PAGE_NUMBER as page_number,
    DESCRIPTION as description,
    REDACTED as redacted,
    INCOME_DURING_REPORTING_PERIOD_CODE as income_during_reporting_period_code,
    INCOME_DURING_REPORTING_PERIOD_TYPE as income_during_reporting_period_type,
    GROSS_VALUE_CODE as gross_value_code,
    GROSS_VALUE_METHOD as gross_value_method,
    TRANSACTION_DURING_REPORTING_PERIOD as transaction_during_reporting_period,
    -- BUG FIXED 2026-08-18 (epoch-1970 investigation): TRANSACTION_DATE_RAW is
    -- CourtListener's own as-extracted OCR text off scanned financial-
    -- disclosure PDFs (confirmed live samples: '04/01/20', '03/25/20', plus
    -- garbled single-digit fragments elsewhere in this family) -- explicitly
    -- not a clean date. A bare try_to_date() epoch-mangled 57,859 of 57,860
    -- rows. TRANSACTION_DATE (below) is the clean, already-working sibling
    -- column. Pass this one through as text; it was never meant to be parsed.
    TRANSACTION_DATE_RAW as transaction_date_raw,
    {{ stg_date('TRANSACTION_DATE') }} as transaction_date,
    TRANSACTION_VALUE_CODE as transaction_value_code,
    TRANSACTION_GAIN_CODE as transaction_gain_code,
    TRANSACTION_PARTNER as transaction_partner,
    HAS_INFERRED_VALUES as has_inferred_values,
    FINANCIAL_DISCLOSURE_ID as financial_disclosure_id
from source
